mapper.select:
SELECT a.id, a.title, a.cover_image AS coverImage, a.episodes, a.rating, YEAR(a.release_date) AS releaseYear, COALESCE(ua.watch_status, 0) AS watchStatus FROM anime a LEFT JOIN user_anime ua ON a.id = ua.anime_id AND ua.user_id = #{userId}
AND ( a.title LIKE CONCAT('%', #{title}, '%') OR a.title_jp LIKE CONCAT('%', #{title}, '%') )
AND YEAR(a.release_date) = #{year}
ORDER BY CASE WHEN a.rating IS NULL THEN 1 ELSE 0 END, a.rating DESC

SELECT a.id, a.title, a.cover_image AS coverImage, a.episodes, a.rating, YEAR(a.release_date) AS releaseYear, ua.watch_status AS watchStatus FROM user_anime ua INNER JOIN anime a ON ua.anime_id = a.id
ua.user_id = #{userId}
AND ( a.title LIKE CONCAT('%', #{title}, '%') OR a.title_jp LIKE CONCAT('%', #{title}, '%') )
AND YEAR(a.release_date) = #{year}
ORDER BY ua.updated_at DESC
